## solutions

#### depth first

```cpp
#include <vector>
#include <string>

std::vector<std::string>* pathFinder(Node* root, std::string targetVal) {
  if (root == nullptr) {
    return nullptr;
  }
  if (root->val == targetVal) {
    return new std::vector<std::string>({ root->val });
  }

  std::vector<std::string>* left = pathFinder(root->left, targetVal);
  if (left != nullptr) {
    left->insert(left->begin(), root->val);
    return left;
  }
  std::vector<std::string>* right = pathFinder(root->right, targetVal);
  if (right != nullptr) {
    right->insert(right->begin(), root->val);
    return right;
  }
  return nullptr;
}
```

- n = number of nodes
- Time: O(n^2)
- Space: O(n)

#### depth first w/ push_back

```cpp
#include <vector>
#include <string>
#include <algorithm>

std::vector<std::string>* _pathFinder(Node* root, std::string targetVal) {
  if (root == nullptr) {
    return nullptr;
  }
  if (root->val == targetVal) {
    return new std::vector<std::string>({ root->val });
  }

  std::vector<std::string>* left = _pathFinder(root->left, targetVal);
  if (left != nullptr) {
    left->push_back(root->val);
    return left;
  }
  std::vector<std::string>* right = _pathFinder(root->right, targetVal);
  if (right != nullptr) {
    right->push_back(root->val);
    return right;
  }
  return nullptr;
}

std::vector<std::string>* pathFinder(Node* root, std::string targetVal) {
  std::vector<std::string>* result = _pathFinder(root, targetVal);
  if (result == nullptr) {
    return nullptr;
  } else {
    std::reverse(result->begin(), result->end());
    return result; 
  }
}
```

- n = number of nodes
- Time: O(n)
- Space: O(n)
